arguments.code:
import os, re
from datetime import datetime

files = apis.file_system.show_directory(access_token=access_token, directory_path='~/photographs/vacations/', recursive=True, entry_type='files')
print('total_files', len(files))

year = datetime.now().year
print('current_year', year)

meta = []
for fp in files:
    info = apis.file_system.show_file(access_token=access_token, file_path=fp)
    created_at = info.get('created_at')
    # created_at format like '2023-02-14T20:19:51'
    dt = datetime.fromisoformat(created_at.replace('Z','')) if created_at else None
    meta.append({'path': fp, 'file_id': info.get('file_id'), 'created_at': created_at, 'dt': dt})

# categorize by month of created_at in the current year
cat = {'Petra': [], 'Budapest': [], 'Amsterdam': []}
for m in meta:
    dt = m['dt']
    if dt and dt.year == year:
        if dt.month == 2:
            cat['Petra'].append(m)
        elif dt.month == 3:
            cat['Budapest'].append(m)
        else:
            cat['Amsterdam'].append(m)
    else:
        # If outside current year, treat as Amsterdam ("others")
        cat['Amsterdam'].append(m)

for k,v in cat.items():
    print(k, 'count', len(v))

# show a few examples per category
for k,v in cat.items():
    print('---', k)
    for m in sorted(v, key=lambda x: x['created_at'])[:5]:
        print(os.path.basename(m['path']), m['created_at'])

